#!/bin/bash
set -euo pipefail

cd "$(dirname "$0")"

# The parser is generated by galop (https://github.com/martianoff/galop), a
# parser generator for ANTLR grammars: download a release binary and put it on
# PATH as `galop`. It reads JsonQuery.g4 (and SemverGrammar.g4, which it
# imports) as ANTLR does and writes jsonquery_lexer.go and jsonquery_parser.go,
# which need no runtime library.
if ! command -v galop >/dev/null 2>&1; then
    echo "Error: galop not found. Download it from https://github.com/martianoff/galop/releases." >&2
    exit 1
fi

galop -Dlanguage=Go -package parser -Xexact-output-dir -o . JsonQuery.g4
